From dd954b6108f658aff49291f13e23fd7abd32c037 Mon Sep 17 00:00:00 2001
From: Jacob Czech <czech.jacob@gmail.com>
Date: Fri, 3 Apr 2015 10:36:17 -0400
Subject: [PATCH] Bugfix: t and t2 (lifetime) not set correctly.

This fixes a bug introduced in 419e20f693ff3e1ba58a450b5cfc072b2f3c8660, which
consolidated the code from place_single_molecule and place_single_molecule_alt.
However, t (the scheduling time), t2 (the lifetime), and the birthday were
always set to zero, which was a problem when using a release pattern to release
at some non-zero time.

diff --git a/src/wall_util.c b/src/wall_util.c
index 2d9cddf4..b78b36e5 100644
--- a/src/wall_util.c
+++ b/src/wall_util.c
@@ -2074,7 +2074,8 @@ int release_onto_regions(struct volume *world, struct release_site_obj *rso,
           failure++;
         else {
           if (place_single_molecule(world, w, grid_index, sm->properties,
-                                    sm->flags, rso->orientation) == NULL) {
+                                    sm->flags, rso->orientation, sm->t, sm->t2,
+                                    sm->birthday) == NULL) {
             return 1;
           }
           success++;
@@ -2133,7 +2134,8 @@ int release_onto_regions(struct volume *world, struct release_site_obj *rso,
             rng_dbl(world->rng) < (this_rrd->my_area / max_A) * ((double)n)) {
           if (place_single_molecule(world, this_rrd->grid->surface,
                                     this_rrd->index, sm->properties, sm->flags,
-                                    rso->orientation) == NULL) {
+                                    rso->orientation, sm->t, sm->t2,
+                                    sm->birthday) == NULL) {
             return 1;
           }

@@ -2185,7 +2187,9 @@ struct surface_molecule *place_single_molecule(struct volume *state,
                                                struct wall *w,
                                                unsigned int grid_index,
                                                struct species *spec,
-                                               short flags, short orientation) {
+                                               short flags, short orientation,
+                                               double t, double t2,
+                                               double birthday) {

   struct vector2 s_pos;
   struct vector3 pos3d;
@@ -2204,9 +2208,9 @@ struct surface_molecule *place_single_molecule(struct volume *state,
                                                       "surface molecule");
   if (new_sm == NULL)
     return NULL;
-  new_sm->t = 0;
-  new_sm->t2 = 0;
-  new_sm->birthday = 0;
+  new_sm->t = t;
+  new_sm->t2 = t2;
+  new_sm->birthday = birthday;
   new_sm->birthplace = w->birthplace->smol;
   new_sm->id = state->current_mol_id++;
   new_sm->grid_index = grid_index;

