          if (smdp->quantity_type == SURFMOLNUM) {
            struct species *sm = smdp->sm;
            short orientation;
            unsigned int n_set = smdp->quantity;
            unsigned int n_clear = n_free_sm - n_set;

            /* Compute orientation */
